local function playMenuSound(assetId, volume)
    local sound = Instance.new("\x53\x6F\x75\x6E\x64")
    sound.Name = "\x79\x30\x75\x6E\x67\x44\x61\x72\x65\x55\x49\x53\x6F\x75\x6E\x64"
    sound.SoundId = "\x72\x62\x78\x61\x73\x73\x65\x74\x69\x64\x3A\x2F\x2F" .. tostring(assetId)
    sound.Volume = volume or 0.7
    sound.Parent = SoundService
    sound:Play()
    Debris:AddItem(sound, 8)
end

local connectedSoundButtons = {}
local function attachButtonSounds(object)
    if not object:IsA("\x47\x75\x69\x42\x75\x74\x74\x6F\x6E") or connectedSoundButtons[object] then return end
    connectedSoundButtons[object] = true
    object.MouseEnter:Connect(function()
        if object.Visible and object.Active then
            playMenuSound(0x567c0a4790f6, 0.6)
        end
    end)
    object.Activated:Connect(function()
        playMenuSound(0x4be7ab04423b, 0.75)
    end)
end

y0ungDareMenuv45.DescendantAdded:Connect(attachButtonSounds)



