	local player = Players.LocalPlayer
	local button = script.Parent
	local enabled = false
	local SPINS_PER_SECOND = 0xc
	
	local connection
	local spinningHumanoid
	local savedAutoRotate
	local generation = 0
	
	local function updateButton()
		button.Text = enabled and "\x53\x70\x69\x6E\x20\x42\x6F\x74\x3A\x20\x4F\x4E" or "\x53\x70\x69\x6E\x20\x42\x6F\x74\x3A\x20\x4F\x46\x46"
		button.BackgroundColor3 = enabled and Color3.fromRGB(0, 0, 0) or Color3.fromRGB(0, 0, 0)
	end
	
	local function stopSpin()
		if connection then
			connection:Disconnect()
			connection = nil
		end
		if spinningHumanoid and spinningHumanoid.Parent and savedAutoRotate ~= nil then
			spinningHumanoid.AutoRotate = savedAutoRotate
		end
		spinningHumanoid = nil
		savedAutoRotate = nil
	end
	
	local function startSpin(character)
		generation += 1
		local thisGeneration = generation
		stopSpin()
		if not enabled then return end
	
		character = character or player.Character
		if not character then return end
	
		local humanoid = character:WaitForChild("\x48\x75\x6D\x61\x6E\x6F\x69\x64", 0xa)
		local root = character:WaitForChild("\x48\x75\x6D\x61\x6E\x6F\x69\x64\x52\x6F\x6F\x74\x50\x61\x72\x74", 0xa)
		if thisGeneration ~= generation or not enabled or character ~= player.Character then return end
		if not humanoid or not root or humanoid.Health <= 0 then return end
	
		spinningHumanoid = humanoid
		savedAutoRotate = humanoid.AutoRotate
		humanoid.AutoRotate = false
	
		connection = RunService.RenderStepped:Connect(function(dt)
			if not enabled or character ~= player.Character or not root.Parent or humanoid.Health <= 0 then
				stopSpin()
				
				return
			end
			root.CFrame = root.CFrame * CFrame.Angles(0, math.rad(0x168 * SPINS_PER_SECOND) * dt, 0)
		end)
	end
	
	button.Activated:Connect(function()
		enabled = not enabled
		if enabled then
			task.spawn(startSpin, player.Character)
		else
			generation += 1
			stopSpin()
		end
		updateButton()
	end)
	
	player.CharacterRemoving:Connect(function()
		generation += 1
		stopSpin()
		
	end)
	
	player.CharacterAdded:Connect(function(character)
		if enabled then
			task.spawn(startSpin, character)
		end
		updateButton()
	end)
	
	updateButton()
	
end
