				local localPlayer = Players.LocalPlayer
	
				local enabled = false
				local transparency = 0.75
				local originals = {}
				local addedConnection
	
				local function shouldChange(part)
				    if not part:IsA("\x42\x61\x73\x65\x50\x61\x72\x74") then return false end
				    if part.Transparency >= 1 then return false end
				    if part:IsA("\x54\x65\x72\x72\x61\x69\x6E") then return false end
