local function DXHC_fake_script() 
	local script = Instance.new('\x4C\x6F\x63\x61\x6C\x53\x63\x72\x69\x70\x74', y0ungDareMenuv45)

	
	
	
	
	local Players = game:GetService("\x50\x6C\x61\x79\x65\x72\x73")
	local RunService = game:GetService("\x52\x75\x6E\x53\x65\x72\x76\x69\x63\x65")
	
	local player = Players.LocalPlayer
	local gui = script:FindFirstAncestorOfClass("\x53\x63\x72\x65\x65\x6E\x47\x75\x69")
	local button = fly 
	
	local Speed = 1.5
	local enabled = false
	local session = 0
	local velocity, gyro, humanoid
	local oldAutoRotate
	local heartbeatConnection
	
	local function updateButton()
		button.Text = enabled and "\x46\x6C\x79\x3A\x20\x4F\x6E" or "\x46\x6C\x79\x3A\x20\x4F\x66\x66"
	end
	
	local function cleanup()
		if heartbeatConnection then
			heartbeatConnection:Disconnect()
			heartbeatConnection = nil
		end
		if velocity then
			velocity:Destroy()
			velocity = nil
		end
		if gyro then
			gyro:Destroy()
			gyro = nil
		end
		if humanoid and humanoid.Parent and humanoid.Health > 0 then
			humanoid.PlatformStand = false
			humanoid.AutoRotate = (oldAutoRotate ~= false)
		end
		humanoid = nil
		oldAutoRotate = nil
	end
	
	local function startFly(character)
		session += 1
		local thisSession = session
		cleanup()
		if not enabled then return end
	
		local human = character:WaitForChild("\x48\x75\x6D\x61\x6E\x6F\x69\x64", 0xa)
		local root = character:WaitForChild("\x48\x75\x6D\x61\x6E\x6F\x69\x64\x52\x6F\x6F\x74\x50\x61\x72\x74", 0xa)
		if not enabled or session ~= thisSession or player.Character ~= character then return end
		if not human or not root or human.Health <= 0 then return end
	
		humanoid = human
		oldAutoRotate = human.AutoRotate
	
		local force = Instance.new("\x42\x6F\x64\x79\x56\x65\x6C\x6F\x63\x69\x74\x79")
		force.Name = "\x79\x30\x75\x6E\x67\x44\x61\x72\x65\x46\x6C\x79\x56\x65\x6C\x6F\x63\x69\x74\x79"
		force.P = 0x3e8
		force.MaxForce = Vector3.new(0x186a0, 0x186a0, 0x186a0)
		force.Velocity = Vector3.zero
		force.Parent = root
	
		local spin = Instance.new("\x42\x6F\x64\x79\x47\x79\x72\x6F")
		spin.Name = "\x79\x30\x75\x6E\x67\x44\x61\x72\x65\x46\x6C\x79\x47\x79\x72\x6F"
		spin.P = 0x2710
		spin.MaxTorque = Vector3.new(0xf4240, 0xf4240, 0xf4240)
		spin.CFrame = root.CFrame
		spin.Parent = root
	
		velocity = force
		gyro = spin
		human.PlatformStand = true
		human.AutoRotate = false
		human:ChangeState(Enum.HumanoidStateType.Freefall)
	
		heartbeatConnection = RunService.Heartbeat:Connect(function()
			if not enabled or session ~= thisSession or player.Character ~= character
				or human.Health <= 0 or not root.Parent then
				if session == thisSession then cleanup() end
				return
			end
	
			local camera = workspace.CurrentCamera
			if not camera then return end
			local cf = camera.CFrame
			local forward = cf.LookVector
			local left = -cf.RightVector
			local horizontalForward = Vector3.new(forward.X, 0, forward.Z)
			if horizontalForward.Magnitude < 0.001 then
				horizontalForward = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
			end
			if horizontalForward.Magnitude < 0.001 then
				horizontalForward = Vector3.new(0, 0, -1)
			end
			horizontalForward = horizontalForward.Unit
			local horizontalRight = Vector3.new(-horizontalForward.Z, 0, horizontalForward.X)
			local move = human.MoveDirection
			local forwardAmount = move:Dot(horizontalForward)
			local rightAmount = move:Dot(horizontalRight)
	
			local push = forward * (0x3c * Speed * forwardAmount)
				+ cf.RightVector * (0x28 * Speed * rightAmount)
			spin.CFrame = CFrame.lookAt(root.Position, root.Position + forward)
			force.Velocity = force.Velocity:Lerp(push, 0.2)
			human.PlatformStand = true
			human.AutoRotate = false
		end)
	end
	
	button.MouseButton1Click:Connect(function()
		enabled = not enabled
		updateButton()
		session += 1
		cleanup()
		if enabled and player.Character then
			task.spawn(startFly, player.Character)
		end
	end)
	
	player.CharacterRemoving:Connect(function()
		session += 1
		cleanup()
		
	end)
	
	player.CharacterAdded:Connect(function(character)
		if enabled then
			task.spawn(startFly, character)
		end
	end)
	
	updateButton()
	if enabled and player.Character then
		task.spawn(startFly, player.Character)
	end
	
end
