         local count=math.clamp(math.floor(length/0xc),1,7)
         for j=1,count do
          local u=(j-(count+1)/2)*math.min(0xc,length/count)
          for _,side in ipairs({-1,1}) do
           local localpos,rotation
           if wideX then
